-- Schema sintético compatível com os tipos reais; não contém dados pessoais.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.actor',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth TO authenticated;
CREATE TABLE empresas(id uuid PRIMARY KEY);
CREATE TABLE public.utilizadores ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"empresa_id" uuid NOT NULL,
"nome" text NOT NULL,
"email" text NOT NULL,
"funcao" text NOT NULL,
"ativo" boolean DEFAULT true NOT NULL,
"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
"auth_user_id" uuid,
"nome_curto" text,
PRIMARY KEY (id));
CREATE TABLE public.colaboradores ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"empresa_id" uuid NOT NULL,
"nome" text NOT NULL,
"funcao" text,
"nivel" text,
"valor_hora" numeric(8,2),
"data_saida" date,
"data_nascimento" date,
"permite_multiplas_obras" boolean DEFAULT false NOT NULL,
"data_admissao" date,
"nif" text,
"email" text,
"contacto" text,
"morada" text,
"codigo_rh" text,
"observacoes" text,
"registo_trabalhador_ok" boolean,
"seguro_ok" boolean,
"seguranca_social_ok" boolean,
"utilizador_id" uuid,
PRIMARY KEY (id));
CREATE TABLE public.obras ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"empresa_id" uuid NOT NULL,
"numero" integer NOT NULL,
"nome" text NOT NULL,
"cliente" text,
"morada" text,
"tipo" text NOT NULL,
"modalidade" text DEFAULT 'cliente_externo'::text NOT NULL,
"diretor_obra_id" uuid,
"situacao" text DEFAULT 'em_curso'::text NOT NULL,
"data_inicio" date,
"data_fim_prevista" date,
"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
"planeamento_baseline_congelado" boolean DEFAULT false NOT NULL,
"planeamento_baseline_congelado_em" timestamp with time zone,
"projeto_id" uuid,
PRIMARY KEY (id));
CREATE TABLE public.obra_responsaveis ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"obra_id" uuid NOT NULL,
"utilizador_id" uuid NOT NULL,
"papel" text NOT NULL,
"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
PRIMARY KEY (id));
CREATE TABLE public.ausencias ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"colaborador_id" uuid NOT NULL,
"data" date NOT NULL,
"tipo" text NOT NULL,
"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
"estado" text DEFAULT 'confirmada'::text NOT NULL,
"comentario" text,
PRIMARY KEY (id));
CREATE TABLE public.quadro_pessoal_alocacao ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"colaborador_id" uuid NOT NULL,
"obra_id" uuid,
"semana_inicio" date NOT NULL,
"criado_por" uuid,
"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
"data" date DEFAULT CURRENT_DATE NOT NULL,
"periodo" text DEFAULT 'dia_inteiro'::text NOT NULL,
"tipo_alocacao" text DEFAULT 'obra'::text NOT NULL,
"descricao_livre" text,
PRIMARY KEY (id));
CREATE TABLE public.quadro_pessoal_movimentos ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"empresa_id" uuid NOT NULL,
"alocacao_id" uuid,
"colaborador_id" uuid NOT NULL,
"data" date NOT NULL,
"periodo" text,
"acao" text NOT NULL,
"obra_origem_id" uuid,
"obra_destino_id" uuid,
"tipo_origem" text,
"tipo_destino" text,
"descricao_origem" text,
"descricao_destino" text,
"alterado_por" uuid,
"alterado_em" timestamp with time zone DEFAULT now() NOT NULL,
"perfil_autor" text,
"nome_autor" text,
"nome_colaborador" text,
"tipo_acao" text,
"alocacao_origem_id" uuid,
"alocacao_destino_id" uuid,
"antes" jsonb,
"depois" jsonb,
PRIMARY KEY (id));
CREATE TABLE public.quadro_pessoal_rpc_permit ("transacao" bigint NOT NULL,
"utilizador_id" uuid NOT NULL,
"colaborador_id" uuid NOT NULL,
"origem_id" uuid,
"destino_id" uuid NOT NULL,
"data" date NOT NULL,
"periodo" text NOT NULL,
PRIMARY KEY (transacao, utilizador_id));
CREATE TABLE public.alertas ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"empresa_id" uuid NOT NULL,
"obra_id" uuid,
"tipo" text NOT NULL,
"entidade_tipo" text,
"entidade_id" uuid,
"titulo" text NOT NULL,
"descricao" text,
"data_evento_referencia" date,
"antecedencia_dias" integer,
"data_gatilho" date NOT NULL,
"recorrencia" text,
"destinatario_role" text,
"destinatario_colaborador_id" uuid,
"estado" text DEFAULT 'pendente'::text NOT NULL,
"resolvido_por" uuid,
"resolvido_em" timestamp with time zone,
"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
"enviar_email" boolean DEFAULT false NOT NULL,
"destinatario_utilizador_id" uuid,
"expira_em" timestamp with time zone,
"ocorrencia_chave" uuid,
PRIMARY KEY (id));
CREATE TABLE colaboradores_contratos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),colaborador_id uuid,tipo_contrato text,data_inicio date,data_fim_prevista date,estado text DEFAULT 'ativo',criado_em timestamptz DEFAULT now());
CREATE TABLE colaboradores_rh_privado(colaborador_id uuid PRIMARY KEY,niss text);
CREATE TABLE rh_cadastro_auditoria(id uuid DEFAULT gen_random_uuid(),empresa_id uuid,colaborador_id uuid,utilizador_id uuid,criado_em timestamptz DEFAULT now(),origem text,antes jsonb,depois jsonb);
CREATE FUNCTION fn_utilizador_atual_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT auth.uid() $$;
CREATE FUNCTION fn_e_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM utilizadores WHERE id=auth.uid() AND ativo AND funcao IN('gestao_plataforma','gerencia')) $$;
CREATE FUNCTION fn_e_administrativo() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT fn_e_admin() OR EXISTS(SELECT 1 FROM utilizadores WHERE id=auth.uid() AND ativo AND funcao='administrativo') $$;
CREATE FUNCTION fn_atualizar_colaborador_ciclo_vida(uuid,text,text,date,date,date,text,numeric,text,text,text,text) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
GRANT SELECT ON public.colaboradores,public.obras,public.utilizadores TO authenticated;
CREATE TABLE ponto_pessoal_obra ("id" uuid DEFAULT gen_random_uuid() NOT NULL,
"empresa_id" uuid NOT NULL,
"obra_id" uuid NOT NULL,
"colaborador_id" uuid NOT NULL,
"data" date NOT NULL,
"periodos_alocados" text[] DEFAULT ARRAY['manha'::text, 'tarde'::text] NOT NULL,
"estado" text NOT NULL,
"entrada_manha" time without time zone,
"saida_manha" time without time zone,
"entrada_tarde" time without time zone,
"saida_tarde" time without time zone,
"horas" numeric(5,2) DEFAULT 0 NOT NULL,
"observacao" text,
"justificacao_estado" text DEFAULT 'nao_aplicavel'::text NOT NULL,
"registado_por" uuid NOT NULL,
"atualizado_por" uuid,
"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
"atualizado_em" timestamp with time zone DEFAULT now() NOT NULL,
UNIQUE (colaborador_id, obra_id, data),
PRIMARY KEY (id));
CREATE FUNCTION fn_e_encarregado_da_obra(uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT false $$;
CREATE FUNCTION fn_ponto_horas(time,time,time,time) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ SELECT (coalesce(extract(epoch from($2-$1)),0)+coalesce(extract(epoch from($4-$3)),0))/3600 $$;
